                table.Rows[row + 1].Cells[0].Paragraphs[0].Text = tasks[row].Task;
                table.Rows[row + 1].Cells[1].Paragraphs[0].Text = tasks[row].Owner;
                table.Rows[row + 1].Cells[2].Paragraphs[0].Text = tasks[row].Status;
            }
        }
    }
}

